import ScriptClass0 from './../../public/scripts/ExamplePulse.node.ts';
import ScriptClass1 from './../../public/scripts/GameMenu/MenuScript.node.ts';
import ScriptClass2 from './../../public/scripts/Gameplay/PlayerMovementScript.node.ts';

function createDynamicNodeModule(ScriptClass, baseName) {
  const probe = new ScriptClass();
  const nodeTypeId = typeof probe.id === 'string' && probe.id.length > 0 ? probe.id : baseName;
  const displayName = typeof probe.name === 'string' && probe.name.length > 0 ? probe.name : nodeTypeId;
  return {
    nodeTypeId,
    displayName,
    createBehavior() {
      return new ScriptClass();
    },
  };
}

const modules = [
  createDynamicNodeModule(ScriptClass0, 'ExamplePulse'),
  createDynamicNodeModule(ScriptClass1, 'GameMenu-MenuScript'),
  createDynamicNodeModule(ScriptClass2, 'Gameplay-PlayerMovementScript')
];

export default { modules };
export { modules };
